from typing import Optional, Any

import pydantic

from ...schemas.rapi.base import BaseRapiResponseSchema


class ThreadAddResultsSchema(pydantic.BaseModel):
    threadId: str


class ThreadAddResponseSchema(BaseRapiResponseSchema):
    results: ThreadAddResultsSchema


class ParentTopic(pydantic.BaseModel):
    chatId: str
    messageId: int
    type: str


class UserState(pydantic.BaseModel):
    lastseen: Optional[int] = None
    state: Optional[str] = None


class TopSubscriber(pydantic.BaseModel):
    sn: str
    userState: UserState


class You(pydantic.BaseModel):
    subscriber: bool


class Person(pydantic.BaseModel):
    sn: str
    friendly: Optional[str] = None
    firstName: Optional[str] = None
    middleName: Optional[str] = None
    lastName: Optional[str] = None


class ThreadGetResultsSchema(pydantic.BaseModel):
    threadId: str
    parentTopic: ParentTopic
    subscribersCount: int
    topSubscribers: list[TopSubscriber]
    you: You
    persons: list[Person]


class ThreadGetResponseSchema(BaseRapiResponseSchema):
    results: ThreadGetResultsSchema


class ThreadSubscribeResponseSchema(BaseRapiResponseSchema): ...


class ThreadUnsubscribeResponseSchema(BaseRapiResponseSchema): ...


class Yours(pydantic.BaseModel):
    lastDelivered: int
    lastRead: int
    lastReadMention: int


class Chat1(pydantic.BaseModel):
    sender: str


class Part(pydantic.BaseModel):
    mediaType: str
    text: str


class PinnedItem(pydantic.BaseModel):
    chat: Chat1
    msgId: int
    parts: Optional[list[Part]]
    text: str
    time: int


class Thread(pydantic.BaseModel):
    threadId: str
    parentTopic: ParentTopic
    repliesCount: Optional[int]
    lastMsgId: int
    noRecentsUpdate: bool
    patchVersion: str
    yours: Optional[Yours]
    draft: Optional[dict[str, Any]]
    messages: list
    pinned: list[PinnedItem]


class ThreadFeedGetResultsSchema(pydantic.BaseModel):
    cursor: Optional[str]
    threads: list[Thread]
    persons: list[Person]


class ThreadFeedGetResponseSchema(BaseRapiResponseSchema):
    results: ThreadFeedGetResultsSchema


class Subscriber(pydantic.BaseModel):
    sn: str
    userState: UserState


class ThreadSubscribersGetResultsSchema(pydantic.BaseModel):
    subscribers: list[Subscriber]
    persons: list[Person]
    cursor: Optional[str]


class ThreadSubscribersGetResponseSchema(BaseRapiResponseSchema):
    results: ThreadSubscribersGetResultsSchema


class ThreadSubscribeSearchResponseSchema(ThreadSubscribersGetResponseSchema): ...


class ThreadAutoSubscribeResponseSchema(BaseRapiResponseSchema): ...
